<template><section class="workspace-page space-y-8"><PageHeader title="Site navigation" description="Arrange safe internal links that follow every published page and business identity."><template #actions><Button type="button" @click="addItem"><Plus class="h-4 w-4" /> Add link</Button></template></PageHeader><StatePanel v-if="loading" kind="loading" title="Loading navigation" message="Retrieving the current site menu." /><form v-else class="max-w-3xl" @submit.prevent="save"><div v-if="items.length" class="divide-y border-y"><div v-for="(item, index) in items" :key="item.id" class="grid gap-3 py-4 sm:grid-cols-[2rem_1fr_1fr_auto] sm:items-end"><span class="font-mono text-xs text-muted-foreground">{{ String(index + 1).padStart(2, '0') }}</span><label class="field-label">Label<Input v-model.trim="item.label" class="mt-1" maxlength="80" required /></label><label class="field-label">Internal path<Input v-model.trim="item.path" class="mt-1" pattern="/[A-Za-z0-9_./-]*" placeholder="/shop" required /></label><Button variant="outline" type="button" @click="items.splice(index, 1)">Remove</Button></div></div><StatePanel v-else title="No navigation links" message="Add the essential paths customers should be able to reach from every page." /><div class="mt-6 flex items-center gap-4"><Button :disabled="saving">{{ saving ? 'Saving…' : 'Save navigation' }}</Button><p class="text-sm" :class="saveError ? 'text-destructive' : 'text-primary'" role="status">{{ message }}</p></div></form></section></template>
<script setup>import { Plus } from 'lucide-vue-next'; const business = useBusinessStore(); const { apiFetch } = useApiClient(); const items = ref([]); const loading = ref(true); const saving = ref(false); const message = ref(''); const saveError = ref(false); onMounted(async () => { if (!business.activeBusiness) await business.loadBusinesses(); const site = await apiFetch(`businesses/${business.activeBusiness.public_id}/site/`); items.value = structuredClone(site.navigation || []); loading.value = false }); function addItem() { items.value.push({ id: crypto.randomUUID(), label: '', path: '/' }) } async function save() { saving.value = true; message.value = ''; try { await apiFetch(`businesses/${business.activeBusiness.public_id}/site/`, { method: 'PATCH', body: { navigation: items.value } }); message.value = 'Navigation saved.'; saveError.value = false } catch (error) { message.value = error?.data?.error?.message || 'Navigation could not be saved.'; saveError.value = true } finally { saving.value = false } }</script>
